def validPath(n: int, edges: list[list[int]], source: int, destination: int) -> bool:
    if source == destination: return True
    parent = list(range(n))
    def find(i):
        if parent[i] == i: return i
        parent[i] = find(parent[i])
        return parent[i]
    for u, v in edges:
        parent[find(u)] = find(v)
